      "exampleEssayTranslation": "Ailem çok büyük değil. Biz dört kişiyiz. Babamın adı Hassan. 55 yaşında ve mühendis olarak çalışıyor. Annemin adı Nour. 50 yaşında ve öğretmen. Bir kız kardeşim var. Adı Sara ve 20 yaşında. Tıp okuyor. Hepimiz Hamburg'da büyük bir dairede birlikte yaşıyoruz. Hafta sonları birlikte yemek yiyoruz ve çok konuşuyoruz. Ailem benim için çok önemlidir.",
